<script module lang="ts">
/**
 * Table.Header: a column header, a `<th>`, with the sort control when the column sorts.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/table.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { Icon, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/table.module.css'

export interface TableHeaderProps {
  children?: Snippet
  numeric?: boolean
  onSort?: () => void
  sortable?: boolean
  /**
   * Controlled by the caller: Table shows the sort control, and DataTable sorts.
   */
  sortDirection?: 'asc' | 'desc'
}
</script>

<script lang="ts">
let {
  children,
  numeric = false,
  onSort,
  sortable = false,
  sortDirection,
}: TableHeaderProps = $props()
const joined = joinSlot(undefined, () => ({}))
</script>

{@render joined.start?.()
}{#if joined.shown
  }<th
    class={styles.header}
    scope="col"
    data-sortable={(sortable) ? '' : undefined}
    data-numeric={(numeric) ? '' : undefined}
    aria-sort={sortDirection === 'asc' ? 'ascending' : sortDirection === 'desc' ? 'descending' : undefined}
    >{#if sortable
      }<button class={styles.sortButton} type="button" onclick={() => { onSort?.() }}
        >{@render children?.()
        }<span class={styles.sortIcon} data-active={(sortDirection !== undefined) ? '' : undefined}
          ><Icon
            name={sortDirection === 'asc' ? 'sort-asc' : sortDirection === 'desc' ? 'sort-desc' : 'sort'}
            size="sm"
        /></span
      ></button
    >{:else
      }{@render children?.()
    }{/if
  }</th
>{/if
}{@render joined.end?.()}
